%\paragraph{Discounting.}
We fix a \emph{discount function}
$\gamma: \mathbb{N} \to \mathbb{R}$ with
$\gamma_t \geq 0$ and $\sum_{t=1}^\infty \gamma_t < \infty$.
Our goal is to maximize discounted rewards $\sum_{t=1}^\infty \gamma_t r_t$.
%
The \emph{discount normalization factor} is defined as
$\Gamma_t := \sum_{k=t}^\infty \gamma_k$.
%
The \emph{effective horizon} $H_t(\eps)$ is a horizon
that is long enough to encompass all but an $\eps$
of the discount function's mass:
\begin{equation}\label{eq:effective-horizon}
H_t(\eps) := \min \{ k \mid \Gamma_{t+k} / \Gamma_t \leq \eps \}
\end{equation}

Let $\eps_t$ be a monotone decreasing sequence of positive reals such that
$\eps_t \to 0$ as $t \to \infty$.
We define our Thompson-sampling policy $\pi_T$ in \autoref{alg:Thompson-sampling}.
\begin{algorithm}
\begin{center}
\begin{algorithmic}[1]
\While{true}
	\State sample $\rho \sim w(\,\cdot \mid \ae_{<t})$
	\State follow $\pi^*_\rho$ for $H_t(\eps_t)$ steps
\EndWhile
\end{algorithmic}
\end{center}
\caption{Thompson sampling policy $\pi_T$}
\label{alg:Thompson-sampling}
\end{algorithm}

Note that $\pi_T$ is a stochastic policy
since we occasionally sample from a distribution.
We assume that this sampling is independent of everything else.

