\begin{definition}[Asymptotic Optimality]
\label{def:asymptotic-optimality}
%-------------------------------%
A policy $\pi$ is
\emph{asymptotically optimal in an environment class $\M$}
iff for all $\mu \in \M$
\begin{equation}\label{eq:asymptotic-optimality}
V^*_\mu(\ae_{<t}) - V^\pi_\mu(\ae_{<t})
\to 0
\text{ as $t \to \infty$}
\end{equation}
on histories drawn from $\mu^\pi$.
\end{definition}

There are different types of asymptotic optimalities
based on the type of stochastic convergence in \eqref{eq:asymptotic-optimality}.
If this convergence occurs almost surely,
it is called \emph{strong asymptotic optimality}~\cite[Def.~7]{LH:2011opt};
if this convergence occurs in mean,
it is called \emph{asymptotic optimality in mean};
if this convergence occurs in probability,
it is called \emph{asymptotic optimality in probability}; and
if the Cesàro averages converge almost surely,
it is called \emph{weak asymptotic optimality}~\cite[Def.~7]{LH:2011opt}.

\end{align*}
\endgroup
By the martingale convergence theorem~\cite[Thm.~5.2.8]{Durrett:2010}
$w(\nu \mid \ae_{<t})$ converges $\xi^{\pi_T}$-almost surely and
because $\xi^{\pi_T} \geq w(\mu) \mu^{\pi_T}$
it also converges $\mu^{\pi_T}$-almost surely.

\end{align*}
\endgroup
and thus we get
\begin{equation}\label{eq:D-bound}
  1 - 4\delta
< w \left[ D_m(\nu^{\pi_T}, \xi^{\pi_T} \mid \ae_{<t})
           < \beta w_{\min}^2
    \;\middle|\; \ae_{<t_0}
    \right].
\end{equation}
In particular, this bound holds for $\nu = \mu$
since $w(\mu \mid \ae_{<t_0}) > 4\delta$ by assumption.

